const NECK_ART={"common": "data:image/webp;base64,", "rare": "data:image/webp;base64,", "epic": "data:image/webp;base64,", "imperial": "data:image/webp;base64,"};
/* item icon by type + rarity (necklaces have one painting per rarity) */
const icoOf=it=>it&&it.type==='amulet'?`<img class="ico-img" alt="" draggable="false" src="${NECK_ART[['common','rare','epic','imperial'][it.rar]||'common']}">`:ICON[it.type];
ICON.amulet=icoOf({type:'amulet',rar:0});
