let uidc=0;
function rollRarity(){const r=Math.random(),L=buffOn('luck')?2:1;if(r<.0001*L)return 3;if(r<.001*L)return 2;if(r<.01*L)return 1;return 0}
const CONS={
  rage:{name:'إكسير الغضب',col:'#ff5d5d',price:150,dur:120,desc:'+٣٠٪ ضرر لك ولمهاراتك لمدة دقيقتين.'},
  iron:{name:'إكسير الحديد',col:'#b8c4d8',price:150,dur:120,desc:'+٢٥٪ حماية إضافية لمدة دقيقتين.'},
  luck:{name:'إكسير الحظ',col:'#7ce0a0',price:250,dur:300,desc:'فرصة الأدوات النادرة ×٢ لمدة ٥ دقائق.'},
  recall:{name:'لفافة العودة',col:'#e8c27a',price:60,desc:'تعيدك إلى التاجر فوراً مع جيشك (زر T). لا تعمل داخل المغارات.',scroll:true},
};
