const buffOn=k=>(S.buffs&&S.buffs[k]||0)>S.t;
function makeItem(type,rar,ilvl){
  const R=RAR[rar];const base=rand(4,7)*R.mult*(1+ilvl*.15);
  return{uid:++uidc,type,rar,ilvl,base,grade:1,power:Math.round(base),name:itemName(type,R.id)};
}
const itemPower=it=>Math.round(it.base*(1+(it.grade-1)*.07));
function fixItem(it){if(!it.grade){it.grade=1;it.base=it.power}
  if(it.type==='boots'&&/^جزمة /.test(it.name||'')){const adj=it.name.slice(5),m={'صدئة':'صدئ','حديدية':'حديدي','جلدية':'جلدي','قديمة':'قديم','مصقولة':'مصقول'};it.name='حذاء '+(m[adj]||adj)}
  return it}
const sameKind=(a,b)=>a.type===b.type&&a.rar===b.rar&&(a.uniq||'')===(b.uniq||'');
const mergeFodder=it=>S.inv.filter(x=>x.uid!==it.uid&&sameKind(x,it))
  .sort((a,b)=>isEquipped(a.uid)-isEquipped(b.uid)||a.grade-b.grade||a.base-b.base)[0];
function mergeTarget(it){
  return S.inv.filter(x=>x!==it&&sameKind(x,it)&&!(x.rar===3&&x.grade>=10)&&!(x.uniq&&x.grade>=10))
    .sort((a,b)=>isEquipped(b.uid)-isEquipped(a.uid)||b.grade-a.grade||b.base-a.base)[0];
}
function autoMerge(it){
  let cur=it,guard=0;
  while(guard++<20&&S.autoMerge){const t=mergeTarget(cur);if(!t||!S.inv.includes(cur))break;mergeInto(t,cur);cur=t}
  if(!$('drawer').hidden)renderInv();
}
function mergeItem(it){mergeInto(it,mergeFodder(it))}
function mergeInto(it,f){
  if(!f)return;
  let g=it.grade+f.grade;it.base=Math.max(it.base,f.base);
  if(g>10&&it.rar<3&&!it.uniq){
    const old=RAR[it.rar].mult;it.rar++;it.base=it.base/old*RAR[it.rar].mult;g-=10;
    it.name=itemName(it.type,RAR[it.rar].id);
    toast(`ترقية! أصبح ${it.name} ${RAR[it.rar].name}`,RAR[it.rar].color,true);
  }else{g=Math.min(10,g);toast(`بلغ ${it.name} المستوى ${AR(g)}`,RAR[it.rar].color)}
  it.grade=g;it.power=itemPower(it);saveSoon();
  const targetWorn=EQK.some(k=>S[k]===it.uid);let transferred=false;
  for(const k of EQK)if(S[k]===f.uid){S[k]=!targetWorn&&!transferred?it.uid:0;transferred=true}
  S.inv=S.inv.filter(x=>x!==f);
}

