    const e=S.aproj[i];e.x+=e.vx*dt;e.y+=e.vy*dt;e.life-=dt;let gone=e.life<=0;
    for(const m of S.mons){if(!m.under&&Math.hypot(m.x-e.x,m.y-12-e.y)<m.r+5){const l=Math.hypot(e.vx,e.vy);hit(m,{d:Math.round(e.dmg*rand(.9,1.1)),crit:false},{x:e.vx/l,y:e.vy/l},e.by);gone=true;break}}
