  for(let i=S.proj.length-1;i>=0;i--){
    const pr=S.proj[i];pr.x+=pr.vx*dt;pr.y+=pr.vy*dt;pr.life-=dt;let gone=pr.life<=0;
    for(const m of S.mons){if(!m.under&&!(pr.hitSet&&pr.hitSet.has(m))&&Math.hypot(m.x-pr.x,m.y-8-pr.y)<m.r+4){const l=Math.hypot(pr.vx,pr.vy);hit(m,calcDmg(pr.it),{x:pr.vx/l,y:pr.vy/l});if(pr.it.uniq==='thornbow'&&!pr.hitSet){pr.hitSet=new Set([m]);pr.life=Math.max(pr.life,.25)}else gone=true;break}}
    if(gone)S.proj.splice(i,1);
  }
  for(let i=S.drops.length-1;i>=0;i--){const dr=S.drops[i];dr.t+=dt;
    if(!p.dead&&dr.t>.6&&canTake(dr.it)){const dx=p.x-dr.x,dy=p.y-dr.y,d=Math.hypot(dx,dy)||1;dr.v=Math.min(1100,(dr.v||120)+1400*dt);const st=Math.min(d,dr.v*dt);dr.x+=dx/d*st;dr.y+=dy/d*st}
    if(!p.dead&&dr.t>.4&&Math.hypot(dr.x-p.x,dr.y-p.y)<30&&pickup(dr))S.drops.splice(i,1);
    else if(dr.t>90&&(dr.it.rar===0||dr.it.potion||dr.it.manaPot))S.drops.splice(i,1)}
  S.haz=S.haz||[];
