    if(f.k==='drop'){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=700*dt}
    if(f.k==='frostp'||f.k==='shard'){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vx*=Math.pow(.25,dt);f.vy*=Math.pow(.25,dt);if(f.k==='shard')f.rot+=f.vr*dt}
