      if(atk.k<.7){handR=[F[0]*scale,F[1]*scale];pull=atk.k<.08?1:0;loaded=pull>0;handL=[handR[0]-Math.cos(angle)*(8.5+pull*12),handR[1]-Math.sin(angle)*(8.5+pull*12)]}
