    const old=LEGACY_MOTION.arms[dn],vx=old.fist[0]-old.pv[0],vy=old.fist[1]-old.pv[1];
    handR=[shoulder.R[0]+(Math.cos(sway)*vx-Math.sin(sway)*vy)*1.2,shoulder.R[1]+(Math.sin(sway)*vx+Math.cos(sway)*vy)*1.2];
    const off=LEGACY_MOTION.offhands[frame.row]?.[frame.col];
    handL=off?[body.N[0]+(off[0]-frame.data.neck[0])*1.2,body.N[1]+(off[1]-frame.data.neck[1])*1.2]:hrLegacyPoint(p.lowerL.b,body);
