  const solve=(side,target)=>{const a=p['upper'+side],b=p['lower'+side],l1=Math.hypot(a.b[0]-a.a[0],a.b[1]-a.a[1]),l2=Math.hypot(b.b[0]-b.a[0],b.b[1]-b.a[1]),reach=Math.hypot(target[0]-shoulder[side][0],target[1]-shoulder[side][1]),stretch=Math.max(1,Math.min(1.16,reach/(l1+l2)));return hrIK(shoulder[side],target,l1*stretch,l2*stretch,side==='L'?1:-1)};
