  const fx=HERO_FX;if(fx&&fx.dead>=0){const q=hrEase(fx.dead/.42);c.rotate((face.x<0?1:-1)*1.45*q);if(fx.dead>2.2)c.globalAlpha*=Math.max(.35,1-(fx.dead-2.2)*.5)}else if(fx&&fx.hurt>=0&&fx.hurt<.24){const q=1-fx.hurt/.24;c.translate(-face.x*4*q,-face.y*3*q*TILT);if(fx.hurt<.09)c.filter='brightness(1.6) sepia(.6)'}
