function drawSkillAura(c,x,y,d,front){const k=d/.9,fade=k<.15?k/.15:1-(k-.15)/.85;if(fade<=0)return;
  c.save();c.globalCompositeOperation='lighter';
  if(!front){c.save();c.translate(x,y);c.scale(1,TILT);
    for(let j=0;j<3;j++){const r=16+k*26+j*7,a0=S.t*(5-j)+j*2.1;c.lineWidth=4-j;
      c.strokeStyle=`rgba(${225-j*30},8,${18+j*6},${.85*fade})`;c.beginPath();c.arc(0,0,r,a0,a0+2.2);c.stroke();
      c.strokeStyle=`rgba(255,${60+j*20},60,${.4*fade})`;c.lineWidth=1;c.beginPath();c.arc(0,0,r-1,a0+.3,a0+1.6);c.stroke()}
    const g=c.createRadialGradient(0,0,4,0,0,44);g.addColorStop(0,`rgba(200,20,20,${.35*fade})`);g.addColorStop(1,'rgba(120,0,0,0)');c.fillStyle=g;c.beginPath();c.arc(0,0,44,0,Math.PI*2);c.fill();c.restore()}
  else{for(let j=0;j<7;j++){const s=(j*137.5)%360*Math.PI/180,ox=Math.cos(s)*12,ph=(S.t*1.6+j*.37)%1,h=18+((j*53)%14);
      c.fillStyle=`rgba(225,${10+j*5},24,${.6*fade*(1-ph)})`;c.beginPath();c.moveTo(x+ox-3,y-4-ph*30);c.quadraticCurveTo(x+ox,y-4-ph*30-h,x+ox+3,y-4-ph*30);c.fill()}
    for(let j=0;j<10;j++){const ph=(S.t*.9+j*.13)%1,ex=x+Math.sin(j*7.3+S.t*2)*16;c.fillStyle=`rgba(255,${70+j*6},60,${fade*(1-ph)})`;c.fillRect(ex,y-8-ph*60,2,2)}}
  c.restore();if(!front)addLight(x,y-20,160*fade,'255,40,30',false)}
function drawHero(c,x,y,s,L,t,moving,face,weapon,swing,hurt,gear){
  c.save();c.translate(x,y);c.scale(s,s);
  const flip=face.x<-.05?-1:1;
  c.fillStyle='rgba(0,0,0,.28)';ell(c,0,0,12,4);
  const bob=moving?Math.abs(Math.sin(t*12))*-2:Math.sin(t*2.5)*.6;
  const step=moving?Math.sin(t*12)*2.2:0;
  c.translate(0,bob);
  const backView=face.y<-.6;
  if(weapon&&backView)drawWeaponAt();
  // legs
  c.fillStyle='#2a2440';rr(c,-6,-11+step*.4,5,10,2);rr(c,1,-11-step*.4,5,10,2);
  c.fillStyle='#4a3628';rr(c,-6.5,-3+step*.4,6,3.5,1.5);rr(c,0.5,-3-step*.4,6,3.5,1.5);
  if(gear&&gear.boots){c.fillStyle='#5a6478';rr(c,-7,-7+step*.4,6.5,7.5,2);rr(c,0.5,-7-step*.4,6.5,7.5,2);c.fillStyle=gear.boots;rr(c,-7,-6+step*.4,6.5,1.6,.8);rr(c,0.5,-6-step*.4,6.5,1.6,.8)}
  // long back hair (female)
  if(L.gender==='f'){c.fillStyle=L.hair;rr(c,-13,-44,26,30,9)}
  // body
  c.fillStyle=L.outfit;rr(c,-8.5,-24,17,15,6);
  if(L.gender==='f'){c.beginPath();c.moveTo(-9,-13);c.lineTo(9,-13);c.lineTo(12,-7);c.lineTo(-12,-7);c.closePath();c.fill()}
  c.fillStyle='rgba(255,255,255,.18)';rr(c,-8.5,-15,17,2.5,1);
  if(gear&&gear.armor){c.fillStyle='#8e97ad';rr(c,-7,-23.5,14,9,4);c.strokeStyle=gear.armor;c.lineWidth=1.4;c.beginPath();c.roundRect?c.roundRect(-7,-23.5,14,9,4):c.rect(-7,-23.5,14,9);c.stroke();
    c.fillStyle='#a7afc2';ell(c,-9,-21.5,4.6,3.4);ell(c,9,-21.5,4.6,3.4);c.fillStyle=gear.armor;ell(c,0,-19.5,1.8,1.8)}
  if(gear&&gear.amulet){c.strokeStyle='#e8d38a';c.lineWidth=.8;c.beginPath();c.arc(0,-25,4.5,.3,Math.PI-.3);c.stroke();c.fillStyle=gear.amulet;c.beginPath();c.moveTo(0,-21.5);c.lineTo(2,-19.5);c.lineTo(0,-17.5);c.lineTo(-2,-19.5);c.closePath();c.fill()}
  c.fillStyle=gear&&gear.gloves?'#6a7488':'#ffe0cc';ell(c,-9.5*flip,-17,gear&&gear.gloves?3.4:2.8,gear&&gear.gloves?3.6:3);ell(c,9.5*flip,-17,gear&&gear.gloves?3.4:2.8,gear&&gear.gloves?3.6:3);
  if(gear&&gear.gloves){c.fillStyle=gear.gloves;rr(c,-9.5*flip-3,-14.5,6,1.4,.7);rr(c,9.5*flip-3,-14.5,6,1.4,.7)}
  // head
  const hx=0,hy=-35;
  c.fillStyle='#ffe3d1';ell(c,hx,hy,11.5,11);
  // hair top
  c.fillStyle=L.hair;c.beginPath();c.arc(hx,hy-1,12.6,Math.PI*1.02,Math.PI*1.98);
  if(!backView){
    c.lineTo(hx+12,hy+2);c.lineTo(hx+8,hy-4);c.lineTo(hx+5,hy+1);c.lineTo(hx+1,hy-5);c.lineTo(hx-3,hy+1);c.lineTo(hx-7,hy-4);c.lineTo(hx-12,hy+3);
  }else{c.lineTo(hx+12.6,hy+8);c.lineTo(hx-12.6,hy+8)}
  c.closePath();c.fill();
  if(L.gender==='m'){c.beginPath();c.moveTo(hx-9,hy-9);c.lineTo(hx-13,hy-17);c.lineTo(hx-4,hy-12);c.lineTo(hx-2,hy-19);c.lineTo(hx+3,hy-12);c.lineTo(hx+11,hy-16);c.lineTo(hx+9,hy-8);c.fill()}
  else{rr(c,hx-13,hy-4,4.5,18,3);rr(c,hx+8.5,hy-4,4.5,18,3);if(!(gear&&gear.helm)){c.fillStyle='#ffd36e';ell(c,hx+8*flip,hy-9,2.6,2.6)}}
  if(gear&&gear.helm){c.fillStyle='#9aa3b8';c.beginPath();c.arc(hx,hy-2,13.6,Math.PI,0);c.lineTo(hx+13.6,hy-1);c.lineTo(hx-13.6,hy-1);c.fill();
    c.fillStyle='#b7bfd0';ell(c,hx-5,hy-10,4,2.4);c.fillStyle=gear.helm;rr(c,hx-13.6,hy-3.5,27.2,3,1.5);
    c.beginPath();c.moveTo(hx-3,hy-15);c.lineTo(hx,hy-24);c.lineTo(hx+3,hy-15);c.fill()}
  if(!backView){
    const ex=face.x*1.6;
    for(const sx of[-4.3,4.3]){
      c.fillStyle='#1b1630';ell(c,hx+sx+ex,hy+2.5,2.9,3.8);
      c.fillStyle=L.eye;ell(c,hx+sx+ex,hy+3.4,2.2,2.6);
      c.fillStyle='#fff';ell(c,hx+sx+ex-.9,hy+1.4,1.1,1.2);
    }
    c.fillStyle='rgba(255,120,140,.35)';ell(c,hx-7+ex,hy+6.5,2.4,1.3);ell(c,hx+7+ex,hy+6.5,2.4,1.3);
    if(hurt){c.strokeStyle='#5a2a2a';c.lineWidth=1;c.beginPath();c.moveTo(hx-2+ex,hy+8.5);c.lineTo(hx+2+ex,hy+8.5);c.stroke()}
  }
  if(weapon&&!backView)drawWeaponAt();
  c.restore();
  function drawWeaponAt(){c.save();c.translate(9.5*flip,-17);drawWeapon(c,weapon.type,weapon.col,Math.atan2(face.y,face.x),swing);c.restore()}
}

