    if(tele){c.fillStyle=`rgba(160,220,255,${.15+k*.3})`;ell(c,0,-50,70+k*20,60+k*16)}
    if(m.soul){c.shadowColor=m.ph2?'#ff9fcf':'#e6f7ff';c.shadowBlur=30}
