    if(tele){c.fillStyle=`rgba(255,160,70,${.15+k*.3})`;ell(c,0,-30,60+k*20,50+k*16)}
    if(m.soul){c.shadowColor=m.ph2?'#ff9a6a':'#f0c9a0';c.shadowBlur=28}
    const col=m.soul?(m.ph2?'#ffb08a':'#f0cfa8'):(m.ph2?'#d9452f':'#c0602f');
    c.scale(m.dir.x<0?-1:1,1);
    drawScorpKing(c,t,m.flash>0?'#fff':col,m.soul?.82:1,m.ph2||tele,m.state==='dash');
