  for(let i=0;i<70;i++){const wx=-90+rnd()*(ARW+180),wy=ARH+40+rnd()*150;x.fillStyle=`rgba(${90+rnd()*60|0},${150+rnd()*60|0},255,${.12+rnd()*.25})`;x.fillRect(wx,wy,6+rnd()*22,1.5)}
