      const q=[[gx+2+rnd()*4,gy+2+rnd()*3],[gx+w*.5,gy+rnd()*2],[gx+w-2-rnd()*4,gy+2+rnd()*3],[gx+w-rnd()*3,gy+h*.5],[gx+w-3-rnd()*3,gy+h-rnd()*3],[gx+w*.5,gy+h+rnd()*2-1],[gx+3+rnd()*3,gy+h-rnd()*3],[gx+rnd()*3,gy+h*.5]];
