  const ed=x.createRadialGradient(ARW/2,ARH/2,ARW*.25,ARW/2,ARH/2,ARW*.62);ed.addColorStop(0,'rgba(0,0,0,0)');ed.addColorStop(1,'rgba(0,0,0,.55)');x.fillStyle=ed;x.fillRect(0,0,ARW,ARH);
  // glowing cracks running from the dais
  x.strokeStyle=`rgba(${C.acc},.55)`;x.lineWidth=2;for(let i=0;i<7;i++){let a=-.4+i*.55+rnd()*.3,px=DAIS.x+Math.cos(a)*DAIS.r,py=DAIS.y+Math.sin(a)*DAIS.r;x.beginPath();x.moveTo(px,py);
    for(let j=0;j<6;j++){a+=(rnd()-.5)*.8;px+=Math.cos(a)*34;py+=Math.sin(a)*34;x.lineTo(px,py)}x.stroke()}
  // scattered goo puddles
  for(const[px,py,r]of[[230,560,46],[860,640,38],[420,720,30],[930,360,26],[160,330,24]]){x.fillStyle=C.goo[0]+'cc';x.beginPath();x.ellipse(px,py,r,r*.55,0,0,Math.PI*2);x.fill();x.fillStyle=C.goo[1]+'aa';x.beginPath();x.ellipse(px-3,py-2,r*.7,r*.38,0,0,Math.PI*2);x.fill();x.fillStyle=C.goo[3]+'66';x.fillRect(px-r*.3,py-r*.2,r*.25,2)}
  x.restore();
  // chasms: rock face on the far (north) side, abyss below, faint water far down
  for(const H of CAVE_HOLES){x.save();pathPts(x,H);x.clip();x.fillStyle=C.wall[1];x.fillRect(0,0,ARW,ARH+100);
    for(let d=0;d<60;d+=6){x.fillStyle=d%12?C.wall[0]:C.wall[2];x.fillRect(0,0,0,0)}
    pathPts(x,H,46);x.fillStyle='#030208';x.fill();
    const wg=x.createLinearGradient(0,0,0,ARH);wg.addColorStop(0,'rgba(30,70,140,.0)');wg.addColorStop(1,'rgba(40,90,170,.25)');pathPts(x,H,46);x.fillStyle=wg;x.fill();
    for(let i=0;i<40;i++){const hx=H[0][0]+rnd()*300-40,hy=H[0][1]+60+rnd()*200;if(inPoly(hx,hy-46,H)){x.fillStyle=`rgba(${100+rnd()*60|0},${170+rnd()*50|0},255,${.15+rnd()*.3})`;x.fillRect(hx,hy,5+rnd()*16,1.5)}}
    for(let i=0;i<60;i++){const hx=H[0][0]-20+rnd()*320,hy=H[0][1]-10+rnd()*260;x.fillStyle='rgba(0,0,0,.35)';x.fillRect(hx,hy,2,6+rnd()*14)}
    x.restore();x.strokeStyle='rgba(0,0,0,.6)';x.lineWidth=4;pathPts(x,H);x.stroke();x.strokeStyle='rgba(255,235,210,.08)';x.lineWidth=1.5;pathPts(x,H,-2);x.stroke()}
