  {const B=CAVE_BRIDGE;for(let bx=B.x0;bx<B.x1;bx+=14){x.fillStyle=(bx/14|0)%2?'#4a3020':'#5a3a26';x.fillRect(bx,B.y0+2,12,B.y1-B.y0-4);x.fillStyle='rgba(0,0,0,.35)';x.fillRect(bx+10,B.y0+2,2,B.y1-B.y0-4)}
    x.fillStyle='#2a1a10';x.fillRect(B.x0,B.y0-2,B.x1-B.x0,4);x.fillRect(B.x0,B.y1-2,B.x1-B.x0,4);
    for(let bx=B.x0+10;bx<B.x1;bx+=48){x.fillStyle='#1e130b';x.fillRect(bx,B.y0-6,5,6);x.fillRect(bx,B.y1,5,6)}}
  // dais: stepped stone rings + goo pool
  for(const[r,col,dy]of[[DAIS.r+26,'#120e0d',10],[DAIS.r+20,C.stone[2],6],[DAIS.r+8,C.stone[3],0],[DAIS.r,'#1a1513',0]]){x.fillStyle=col;x.beginPath();x.ellipse(DAIS.x,DAIS.y+dy,r,r*.78,0,0,Math.PI*2);x.fill()}
  for(let i=0;i<36;i++){const a=i/36*Math.PI*2;x.save();x.translate(DAIS.x+Math.cos(a)*(DAIS.r+14),DAIS.y+Math.sin(a)*(DAIS.r+14)*.78);x.rotate(a+Math.PI/2);x.fillStyle=C.stone[i%4];x.fillRect(-13,-6,26,12);x.fillStyle='rgba(255,240,220,.08)';x.fillRect(-12,-6,24,2);x.restore()}
  // steps toward the player side
  for(let s=0;s<4;s++){const yy=DAIS.y+DAIS.r*.78+6+s*14,w=150-s*0;x.fillStyle=s%2?C.stone[1]:C.stone[3];x.fillRect(DAIS.x-w/2,yy,w,12);x.fillStyle='rgba(0,0,0,.35)';x.fillRect(DAIS.x-w/2,yy+10,w,3);x.fillStyle='rgba(255,240,220,.07)';x.fillRect(DAIS.x-w/2,yy,w,2)}
  // goo pool on the dais
  const gp=[];for(let i=0;i<22;i++){const a=i/22*Math.PI*2,r=(DAIS.r-22)*(.82+rnd()*.18);gp.push([DAIS.x+Math.cos(a)*r,DAIS.y+Math.sin(a)*r*.74])}
