function startGame(data){
  if(data&&data.p)data=softValidate(data)||data;
  $('creator').hidden=true;$('hudLayer').hidden=false;
  if(data&&data.p){Object.assign(look,data.look);S.p=data.p;S.inv=data.inv.map(fixItem);S.eq=data.eq;for(const g of GSLOTS)S[g[1]]=data[g[1]]||0;S.skillT={};S.pend=[];S.p.invT=0;S.p.rootT=0;S.p.slowT=0;S.p.mana=S.p.mana??50+S.p.lvl*5;S.kills=data.kills||0;uidc=data.uidc||uidc;S.p.dead=false;S.potions=data.potions??3;S.clears=data.clears||0;
    S.army=(data.army||(data.ally?[{...data.ally,type:'queen'}]:[])).map(a=>({shotT:2,dashT:0,dashCd:2,burstT:2,face:1,...a,type:a.type||'queen'}));
    S.zone=data.zone||1;S.cleared=data.cleared||{};S.gold=data.gold||0;S.manaPots=0;S.potions=Math.min(POT_MAX,(S.potions||0)+(data.manaPots||0));S.bagMax=data.bagMax||24;S.stock=[];S.autoMerge=data.autoMerge??true;S.story=data.story||null;S.uniqPity=data.uniqPity||{};S.uniqGot=data.uniqGot||{};S.gifts=data.gifts||{};S.reactSeen=data.reactSeen||{};S.cons={rage:0,iron:0,luck:0,recall:0,...(data.cons||{recall:2})};S.buffs={};S._buffsLeft=data.buffsLeft||{};if(S.clears>0||S.army.some(a=>a.type==='queen'))S.cleared.queen=true;
    if(!S.inv.some(i=>i.uid===S.eq&&!isGear(i.type))){const w=S.inv.find(i=>!isGear(i.type));if(w)S.eq=w.uid}
    S.army.forEach((a,i)=>{a.x=S.p.x+(i?50:-50);a.y=S.p.y+20});
    S.t=0;const old=S.t-10;for(const k in (S._buffsLeft||{}))S.buffs[k]=S._buffsLeft[k];S._buffsLeft=null;S.p.lastAtk=S.p.atkT=S.p.lastHit=old;S.p.deadT=0;S.potT=old;S.paused=false;keys.clear();atkHeld=false;
    for(const a of S.army){a.lastHurt=a.atkT=old;a.down=false;a.dashT=0;a.hp=clamp(a.hp,1,allyMaxHp(a))}
    /* Test weapon gifts removed; existing inventory and gift flags are preserved. */
    $('drawer').hidden=true;$('cavePrompt').hidden=true;$('soulPrompt').hidden=true;$('death').hidden=true}
  else{newPlayer();S.clears=0;S.story=newStory();storyEvent('arrive',700)}
  S.scene='field';S.cam.x=S.p.x-VW/2;S.cam.y=S.p.y*TILT-VH/2;S.mons=[];S.drops=[];S.running=true;
  lastSave=S.t;$('nameIn').blur();
  if(data&&data.p&&!S.story){S.story=catchUpStory();S.story.seen.recap=0;storyEvent('recap',600)}
  if(!data||!data.p)saveGame();
}

/* ---------- permanent save: your account (db) + this browser as backup ---------- */
const SAVE_KEY='caves-of-souls-save-v1';
/* Validate before touching a running game or replacing an existing save. */
/* strict check, but a save that fails it is still loaded as-is (never lost) */
function softValidate(raw){try{return validateSave(raw)}catch(e){console.warn('save check:',e&&e.message);return raw&&raw.p&&Array.isArray(raw.inv)?raw:null}}
function validateSave(raw){
  if(!raw||typeof raw!=='object'||Array.isArray(raw)||!raw.p||!Array.isArray(raw.inv))throw Error('save structure');
  const d=JSON.parse(JSON.stringify(raw)),p=d.p;
  const num=(n,min=0,max=1e12)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;
  if(d.v!=null&&d.v!==1)throw Error('save version');
  if(!num(p.x,0,S.W)||!num(p.y,0,S.H)||!Number.isInteger(p.lvl)||!num(p.lvl,1,10000)||!num(p.hp)||!num(p.exp??0))throw Error('player');
  if(!d.inv.length||d.inv.length>63)throw Error('inventory');
  const ids=new Set();
  for(const it of d.inv){
    if(!it||!(Object.hasOwn(WEAP,it.type)||Object.hasOwn(GEAR,it.type))||!Number.isInteger(it.uid)||!num(it.uid,1)||ids.has(it.uid)||!Number.isInteger(it.rar)||!num(it.rar,0,3)||!num(it.power))throw Error('item');
    if(it.grade!=null&&(!Number.isInteger(it.grade)||!num(it.grade,1,10)))throw Error('item grade');
    if(it.base!=null&&!num(it.base))throw Error('item base');
    if(it.ilvl!=null&&!num(it.ilvl,1,10000))throw Error('item level');
    if(it.uniq&&!Object.hasOwn(UNIQ,it.uniq))throw Error('unique item');
    ids.add(it.uid);it.name=String(it.name||(WEAP[it.type]||GEAR[it.type]).name).replace(/[<>]/g,'').slice(0,100);
  }
  if(!d.inv.some(it=>Object.hasOwn(WEAP,it.type)))throw Error('weapon missing');
  const weapon=d.inv.find(it=>it.uid===d.eq&&Object.hasOwn(WEAP,it.type));d.eq=(weapon||d.inv.find(it=>Object.hasOwn(WEAP,it.type))).uid;
  const equipped=new Set([d.eq]);
  for(const [type,key]of GSLOTS){const it=d.inv.find(it=>it.uid===d[key]&&it.type===type);d[key]=it&&!equipped.has(it.uid)?it.uid:0;if(d[key])equipped.add(d[key])}
  d.zone=d.zone??1;if(!Object.hasOwn(ZONES,d.zone))throw Error('zone');
  d.gold=d.gold??0;if(!num(d.gold))throw Error('gold');
  for(const k of ['potions','manaPots']){d[k]=d[k]??(k==='potions'?3:0);if(!Number.isInteger(d[k])||!num(d[k],0,9))throw Error('potions')}
  d.bagMax=Math.max(d.inv.length,d.bagMax??24);if(!Number.isInteger(d.bagMax)||!num(d.bagMax,24,63))throw Error('bag');
  d.uidc=Math.max(...ids,d.uidc||0);if(!Number.isSafeInteger(d.uidc))throw Error('item counter');
  p.exp=p.exp??0;p.face=p.face||{x:1,y:0};
  if(!num(p.face.x,-1,1)||!num(p.face.y,-1,1))throw Error('facing');
  for(const k of ['invT','rootT','slowT','mana','lastAtk','atkT','lastHit','deadT','auraT'])if(p[k]!=null&&!num(p[k],-1e12,1e12))throw Error('player timer');
  d.army=d.army||(d.ally?[{...d.ally,type:d.ally.type||'queen'}]:[]);
  if(!Array.isArray(d.army)||d.army.length>4)throw Error('army');
  const armyTypes=new Set();
  for(const a of d.army){a.type=a.type||'queen';if(!Object.hasOwn(ALLIES,a.type)||armyTypes.has(a.type)||!Number.isInteger(a.lvl)||!num(a.lvl,1,10000)||!num(a.hp)||!num(a.exp??0))throw Error('ally');armyTypes.add(a.type);a.exp=a.exp??0}
  for(const k of ['cleared','uniqPity','uniqGot','gifts','cons','buffsLeft','reactSeen']){d[k]=d[k]||{};if(typeof d[k]!=='object'||Array.isArray(d[k]))throw Error('save section')}
  for(const k of Object.keys(CONS)){d.cons[k]=d.cons[k]??0;if(!Number.isInteger(d.cons[k])||!num(d.cons[k],0,9))throw Error('consumable');if(d.buffsLeft[k]!=null&&!num(d.buffsLeft[k],0,86400))throw Error('buff')}
  validateExpansionSave(d);
  if(d.story){if(typeof d.story!=='object'||!d.story.seen||typeof d.story.seen!=='object'||!Array.isArray(d.story.pages)||d.story.pages.some(k=>!Object.hasOwn(PAGES,k)))throw Error('story')}
  d.look=d.look||{};if(typeof d.look!=='object'||Array.isArray(d.look))throw Error('appearance');
  d.look.name=String(d.look.name||'بطل').replace(/[<>]/g,'').slice(0,16);
  for(const [key,list]of [['hairDye',DYE_HAIR],['shirtDye',DYE_SHIRT],['skinTone',HERO_SKIN],['scarfDye',HERO_SCARF]])if(!Number.isInteger(d.look[key])||!list[d.look[key]])d.look[key]=0;
  if(d.savedAt!=null&&!num(d.savedAt,0,Number.MAX_SAFE_INTEGER))throw Error('save timestamp');
  d.v=1;return d;
}
function writeLocalSave(data){
  if(trialMode)return false;
  try{const previous=localStorage.getItem(SAVE_KEY);if(previous){try{validateSave(JSON.parse(previous));localStorage.setItem(SAVE_KEY+'-backup',previous)}catch(e){}}
    localStorage.setItem(SAVE_KEY,JSON.stringify(data));return true}catch(e){return false}
}

const store={ref:null,ready:null};let lastSave=0,saving=false,pendingSave=null,armedNew=false;
function snapshotState(){
  if(!S.running||!S.p)return null;
  const p=S.p,pos=S.scene==='cave'&&S.field?{x:S.field.x,y:S.field.y}:p.dead?{x:S.W/2,y:S.H/2}:{x:p.x,y:p.y};
  return JSON.parse(JSON.stringify({v:1,p:{...p,...pos,dead:false,hp:p.dead?mhp():p.hp},inv:S.inv,eq:S.eq,...Object.fromEntries(GSLOTS.map(g=>[g[1],S[g[1]]])),kills:S.kills,uidc,look,
    potions:S.potions,army:S.army,armyMode:S.armyMode,zone:S.zone,cleared:S.cleared,clears:S.clears,gold:S.gold,manaPots:S.manaPots,bagMax:S.bagMax,autoMerge:S.autoMerge,story:S.story,uniqPity:S.uniqPity||{},uniqGot:S.uniqGot||{},gifts:S.gifts||{},cons:S.cons,buffsLeft:Object.fromEntries(Object.keys(S.buffs||{}).filter(buffOn).map(k=>[k,S.buffs[k]-S.t])),reactSeen:S.reactSeen||{},savedAt:Date.now()}));
}
function setSaveChip(txt,ok){const c=$('saveChip');c.textContent=txt;c.classList.toggle('ok',!!ok)}
async function initStore(){
  try{
    const c=window.claude;if(!c||!c.use)return;
    const[db,user]=await Promise.all([c.use('db'),c.use('user')]);if(!db||!user)return;
    const id=await user.id();if(!id)return;
    store.ref=db.doc('data/users/'+id+'/save');
  }catch(e){}
}
async function loadSave(){
  const candidates=[];
  for(const key of [SAVE_KEY,SAVE_KEY+'-backup']){try{const raw=JSON.parse(localStorage.getItem(key)||'null');const v=raw&&softValidate(raw);if(v)candidates.push(v)}catch(e){}}
  if(store.ref){try{const snap=await store.ref.get();if(snap.exists){const v=softValidate(snap.data());if(v)candidates.push(v)}}catch(e){}}
  return candidates.sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))[0]||null;
}
async function saveGame(){
  if(trialMode){saveTrial();return}
  const data=snapshotState();if(!data)return;lastSave=S.t;
  const local=writeLocalSave(data);
  if(store.ready)await store.ready;
  if(!store.ref){setSaveChip(local?'محفوظ في هذا المتصفح':'الحفظ غير متاح هنا',local);return}
  if(saving){pendingSave=true;return}
  saving=true;
  try{await store.ref.set(data);setSaveChip('محفوظ في حسابك',true)}
  catch(e){setSaveChip(local?'محفوظ في هذا المتصفح':'تعذّر الحفظ',local)}
  finally{saving=false;if(pendingSave){pendingSave=false;saveGame()}}
}
const saveSoon=()=>{lastSave=Math.min(lastSave,S.t-13)};
addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveGame()});
addEventListener('pagehide',()=>saveGame());
addEventListener('cos-before-update',()=>saveGame());

function showContinue(save){
  if(S.running||!save)return;
  const army=save.army||(save.ally?[{...save.ally,type:'queen'}]:[]),box=$('contBox');
  $('contName').textContent=save.look&&save.look.name||'بطلك';
  $('contMeta').textContent=`المستوى ${AR(save.p.lvl)} · ${AR(save.kills||0)} وحش · ${AR((save.inv||[]).length)} أداة`+` · ${ZONES[save.zone||1].title}`+army.map(x=>` · ${allyName({type:'queen',...x})} Lv${x.lvl}`).join('');
  box.hidden=false;tsMark();
  $('contBtn').onclick=()=>{startGame(save);toast('مرحباً بعودتك! تقدّمك محفوظ','#7ce0c3')};
  S.savedGame=save;$('contBtn').focus();
}
