document.querySelectorAll('.ts-item').forEach(b=>{b.addEventListener('mouseenter',()=>{document.querySelectorAll('.ts-item').forEach(x=>x.classList.toggle('on',x===b))});b.addEventListener('focus',()=>{document.querySelectorAll('.ts-item').forEach(x=>x.classList.toggle('on',x===b))})});
{const ash=$('tsAsh');if(ash)ash.innerHTML=Array.from({length:36},()=>`<i style="left:${(Math.random()*110).toFixed(1)}%;animation-duration:${(7+Math.random()*9).toFixed(1)}s;animation-delay:-${(Math.random()*16).toFixed(1)}s;transform:scale(${(.6+Math.random()*1.2).toFixed(2)})"></i>`).join('')}
