async function beginTrial(){if(!/^(RAVEN5|غراب)$/i.test($('trialPassword').value.trim())){$('trialError').textContent='كلمة المرور غير صحيحة.';return}
 const z=Number($('trialZone').value),weapon=$('trialWeapon').value;if(!ZONES[z]||!WEAP[weapon])return;$('trialStart').disabled=true;
 try{if(S.running&&!trialMode)await saveGame();await EXPANSION_READY;trialMode=true;trialGod=$('trialImmortal').checked;
  const savedLook=S.savedGame?.look||look;Object.assign(look,savedLook);if(!look.name)look.name='الوريث';
  const lvl=[0,8,18,28,38,46][z],inv=[];for(const type of Object.keys(WEAP)){const it=makeItem(type,1,lvl);it.base=(12+lvl*.8)*1.6;it.grade=4;it.power=itemPower(it);inv.push(it)}
  const gear={};for(const[type,slot]of GSLOTS){const it=makeItem(type,1,lvl);it.grade=3;it.power=itemPower(it);inv.push(it);gear[slot]=it.uid}
  const clears={};for(const key of BOSS_ORDER.slice(0,z-1))clears[key]=true;
  const army=Object.keys(ALLIES).sort((a,b)=>ALLIES[a].tier-ALLIES[b].tier).filter(k=>ALLIES[k].tier<z).map((k,i)=>{const a=newAlly(k,1300+i*35,2130);a.lvl=Math.min(ALLIES[k].max,Math.max(ALLIES[k].start,lvl-4));a.hp=allyMaxHp(a);a.plan={role:i===0?'front':i===1?'attack':'rear',priority:i===3?'caster':'nearest',ability:'auto'};return a});
  const st=newStory();st.tactics=z;st.pending=[];st.log=[];for(const id of ['arrive','b_queen','z2','b_scorp','z3','b_frost','z4','b_thorn']){const ez=id==='arrive'?1:id==='z2'||id==='b_scorp'?2:id==='z3'||id==='b_frost'?3:id==='z4'||id==='b_thorn'?4:1;if(ez<z){st.seen[id]=1;const E=STORY[id];if(E?.page&&!st.pages.includes(E.page))st.pages.push(E.page);if(E?.alive!=null)st.alive=Math.min(st.alive,E.alive)}}
  const data={v:1,p:{x:ZONES[z].spawn.x,y:ZONES[z].spawn.y,lvl,exp:0,hp:9999,face:{x:0,y:-1},mana:100,lastAtk:-9,atkT:-9,lastHit:-9,atkDir:{x:0,y:-1}},inv,eq:inv.find(i=>i.type===weapon).uid,...gear,kills:0,uidc,look:{...look},potions:9,army,zone:z,cleared:clears,clears:z-1,gold:15000,bagMax:36,autoMerge:true,story:st,cons:{rage:3,iron:3,luck:3,recall:3}};
  closeExtra('trialModal');startGame(data);S.p.hp=mhp();$('trialExit').hidden=false;storyEvent(z===1?'arrive':'z'+z,200);toast('جلسة تجربة منفصلة. حفظ مغامرتك لم يتغيّر.','#ffd680',true)
 }finally{$('trialStart').disabled=false}}
$('trialStart').onclick=beginTrial;
$('trialExit').onclick=()=>{if(!$('story').hidden||birdFlight>0)return;renderTrialActions()};
function renderTrialActions(){openPrompt({eyebrow:'جلسة تجربة منفصلة',title:'اختصارات التجربة',body:'تقدر تنتقل إلى مدخل الزعيم مباشرة، أو ترجع للقائمة وتختار منطقة ثانية.',note:'لا يتم تعديل حفظ مغامرتك الأساسي.',ok:'إلى مدخل الزعيم',action:()=>{if(S.scene==='cave')leaveCave();const cave=caveHere();S.p.x=cave.x;S.p.y=cave.y+115;S.p.hp=mhp();S.promptCool=true;S.cam.x=S.p.x-VW/2;S.cam.y=S.p.y*TILT-VH/2;}});$('cpWarn').replaceChildren();const b=document.createElement('button');b.type='button';b.textContent='إنهاء التجربة والرجوع للقائمة';b.style.cssText='padding:10px;margin-top:10px;color:#e8ca94;background:#231c1d;border:1px solid #947747;font:inherit';b.onclick=exitTrial;$('cpWarn').append(b)}
function exitTrial(){sessionSerial++;activeScene=null;birdFlight=birdVisible=0;quickOrder=focusTarget=null;S.storyQ=[];trialMode=false;trialGod=false;S.running=false;S.paused=false;for(const id of ['story','drawer','shop','cavePrompt','soulPrompt','planModal','journalModal','trialModal','death','trialExit','commandDock','questLine'])$(id).hidden=true;$('bossBar').hidden=true;$('app').classList.remove('in-cave');$('hudLayer').hidden=true;$('creator').hidden=false;$('creatorPanel').hidden=true;S.savedGame=null;$('contBox').hidden=true;loadSave().then(showContinue);tsMark()}
