/* ---------- loop ---------- */
let last=performance.now();
function frame(now){
  requestAnimationFrame(frame);
  const dt=Math.max(0,Math.min(.05,(now-last)/1000));last=now;
  try{
  setTheme(!S.running?'menu':S.scene==='cave'&&S.mons.some(m=>m.kind==='boss')?'boss':'z'+S.zone);
  if(S.running){if(!S.paused)update(dt);render();hudT-=dt;if(hudT<=0){hud();hudT=.1}
    if(S.t-lastSave>15)saveGame()}
  else{drawPreview(dt);ctx.setTransform(DPR*ZM,0,0,DPR*ZM,0,0);ctx.fillStyle='#1a2c2a';ctx.fillRect(0,0,VW,VH)}
  }catch(err){console.error(err)}
}

