{const enc=o=>'COS1:'+btoa(unescape(encodeURIComponent(JSON.stringify(o)))),dec=t=>JSON.parse(decodeURIComponent(escape(atob(t.trim().replace(/^COS1:/,'')))));
 const open=(mode)=>{$('xfer').hidden=false;const ta=$('xferTxt');$('xferGo').hidden=mode!=='in';
   if(mode==='out'){const d=snapshotState();ta.value=d?enc(d):'';$('xferTitle').textContent='رمز الحفظ';$('xferNote').textContent='يحوي هذا الرمز شخصيتك كاملة. انسخه والصقه في الجهاز الآخر من شاشة البداية ← «لديّ رمز حفظ».';ta.readOnly=true;ta.focus();ta.select();
     try{navigator.clipboard.writeText(ta.value).then(()=>$('xferNote').textContent='✓ نُسخ الرمز تلقائياً. الصقه في الجهاز الآخر من شاشة البداية ← «لديّ رمز حفظ».',()=>{})}catch(e){}}
   else{ta.value='';ta.readOnly=false;$('xferTitle').textContent='حمّل حفظ';$('xferNote').textContent='الصق رمز الحفظ هنا. تنبيه: يحل الرمز محل أي حفظ موجود على هذا الجهاز.';ta.focus()}};
 $('exportBtn').onclick=()=>{saveGame();open('out')};
 $('importBtn').onclick=()=>open('in');
 $('xferClose').onclick=()=>{$('xfer').hidden=true;cv.focus()};
 $('xferGo').onclick=()=>{let d;try{if($('xferTxt').value.length>2000000)throw Error('save too large');d=validateSave(dec($('xferTxt').value))}catch(e){$('xferNote').textContent='رمز الحفظ ناقص أو غير متوافق. لم يتغيّر حفظك الحالي؛ تأكد من نسخ الرمز كاملاً.';return}
   d.savedAt=Date.now();startGame(d);$('xfer').hidden=true;saveGame();toast('تم نقل حفظك! أهلاً '+(d.look&&d.look.name||''),'#7ce0c3',true)}}
const boot=data=>{
  store.ready=initStore();
  let seenIntro=false;try{seenIntro=localStorage.getItem('cos-intro')==='1'}catch(e){}
  if(data&&data.p){try{startGame(data);store.ready.then(()=>saveGame())}catch(e){store.ready.then(loadSave).then(showContinue)}}
  else store.ready.then(loadSave).then(showContinue);
  requestAnimationFrame(frame);
};
hot&&hot.ready?hot.ready(boot):boot((hot&&hot.data)||{});
